    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "minutes must be 1 through 60")
    }
}
impl std::error::Error for InvalidMinutes {}
fn parse_minutes(text: &str) -> Result<u8, InvalidMinutes> {
    let n = text.parse::<u8>().map_err(|_| InvalidMinutes)?;
    if !(1..=60).contains(&n) { return Err(InvalidMinutes); }
    Ok(n)
}
